bool getPCRelativeBase(const MCInst &Inst, MCPhysReg &Reg,
                       int64_t &Disp) const override {
  switch (Inst.getOpcode()) {
  case ARM::ADR:
    // (Rd, imm, pred, predreg); the decoder stores the signed offset.
    if (MCPlus::getNumPrimeOperands(Inst) < 4 || !Inst.getOperand(1).isImm() ||
        !Inst.getOperand(2).isImm() || Inst.getOperand(2).getImm() != ARMCC::AL)
      return false;
    Reg = Inst.getOperand(0).getReg();
    Disp = Inst.getOperand(1).getImm();
    return true;
  case ARM::ADDri:
  case ARM::SUBri:
    // (Rd, Rn, imm, pred, predreg, cc_out): Rn = PC, no flag update.
    if (MCPlus::getNumPrimeOperands(Inst) < 6 || !Inst.getOperand(1).isReg() ||
        Inst.getOperand(1).getReg() != ARM::PC || !Inst.getOperand(2).isImm() ||
        !Inst.getOperand(3).isImm() || Inst.getOperand(3).getImm() != ARMCC::AL ||
        !Inst.getOperand(5).isReg() || Inst.getOperand(5).getReg())
      return false;
    Reg = Inst.getOperand(0).getReg();
    Disp = Inst.getOpcode() == ARM::ADDri ? Inst.getOperand(2).getImm()
                                          : -Inst.getOperand(2).getImm();
    return Reg != ARM::PC;
  default:
    return false;
  }
}

